INSERT INTO public.reference_cases (slug, title, location, year, summary, tagline, meta_description, hero_image, facts, story_title, story_text, story_image, quote_text, quote_author, gallery, features, location_title, location_text, location_image, specs, related_project_slug, published, sort_order)
VALUES (E'sudenkorento-6-a-ja-b', E'Sudenkorento 6 A ja B', E'Liminka', E'2026', E'Kaksi valoisaa 82,5 m\u00b2 erillistaloa Limingan Kotirannassa. Valttikotien ensimm\u00e4iset valmistuneet kodit ovat jo l\u00f6yt\u00e4neet omistajansa.', E'Kaksi kotia, joissa jokainen neli\u00f6 on mietitty arkea varten. Valttikotien ensimm\u00e4iset valmistuneet kodit ovat jo l\u00f6yt\u00e4neet omistajansa.', E'Tutustu Valttikotien ensimm\u00e4isiin valmistuneisiin koteihin: Sudenkorento 6 A ja B Limingan Kotirannassa. Valoisat 82,5 m\u00b2 erillistalot, A-energialuokka ja huolella mietityt ratkaisut.', E'assets/img/referenssit/sudenkorento/sk-0099-2000.jpg', $j$[{"label": "kotia myyty", "value": "2 / 2"}, {"label": "4 huonetta, keitti\u00f6 ja sauna", "value": "82,5 m\u00b2"}, {"label": "energialuokka", "value": "A"}, {"label": "valmistunut Limingan Kotirantaan", "value": "2026"}]$j$::jsonb, E'Koti, johon on varaa ja jossa arki toimii', E'Moni haaveilee omasta erillistalosta, mutta hinta ja rakentamisen ep\u00e4varmuus pys\u00e4ytt\u00e4v\u00e4t. Halusimme n\u00e4ytt\u00e4\u00e4, ett\u00e4 laadukas, valoisa ja energiatehokas koti voi olla my\u00f6s kohtuuhintainen.\n\nSudenkorento 6 A ja B on t\u00e4h\u00e4n vastauksemme: kaksi erillistaloa yhdell\u00e4 tontilla, jolloin tontin kustannukset jakautuvat kahden kodin kesken. Tuloksena on omakotiasumisen vapaus ilman turhia kuluja.\n\nVaikka talot ovat saman kokoiset, ne saivat omat ilmeens\u00e4: A:n keitti\u00f6 on vaalea ja raikas, B:n tumma ja tyylik\u00e4s.', E'assets/img/referenssit/sudenkorento/sk-0024-1600.jpg', E'Suurin osa rakennusten kustannuksista p\u00e4\u00e4tet\u00e4\u00e4n suunnittelup\u00f6yd\u00e4ll\u00e4. Me haluamme suunnitella ja rakentaa aikaa kest\u00e4vi\u00e4, arjessa toimivia pientaloja, joihin asiakkaalla on varaa.', E'Jani Junes, toimitusjohtaja, Valttikodit Oy', $j$[{"alt": "Musta puuverhoiltu julkisivu ja l\u00e4mmin sis\u00e4\u00e4nk\u00e4ynti", "url": "assets/img/referenssit/sudenkorento/sk-0100-1600.jpg", "caption": "Musta puuverhous ja l\u00e4mmin sis\u00e4\u00e4nk\u00e4ynti"}, {"alt": "Puuverhoiltu sis\u00e4\u00e4nk\u00e4ynti ja tumma ulko-ovi", "url": "assets/img/referenssit/sudenkorento/sk-0056-1600.jpg", "caption": "Sis\u00e4\u00e4nk\u00e4ynti puun ja mustan yhdistelm\u00e4n\u00e4"}, {"alt": "Kaksi erillistaloa katoksineen ilmasta kuvattuna", "url": "assets/img/referenssit/sudenkorento/sk-0102-1600.jpg", "caption": "Kaksi erillistaloa ilmasta"}, {"alt": "Valoisa olohuone ja suuri ikkuna", "url": "assets/img/referenssit/sudenkorento/sk-0005-1600.jpg", "caption": "Olohuone, jossa valoa riitt\u00e4\u00e4"}, {"alt": "Koti A: vaalea keitti\u00f6 ja ruokailuryhm\u00e4 suuren ikkunan \u00e4\u00e4rell\u00e4", "url": "assets/img/referenssit/sudenkorento/sk-0037-1600.jpg", "caption": "Koti A: vaalea keitti\u00f6 ison ikkunan \u00e4\u00e4rell\u00e4"}, {"alt": "Koti B: tumma keitti\u00f6 ja py\u00f6re\u00e4 ruokap\u00f6yt\u00e4 suuren ikkunan vieress\u00e4", "url": "assets/img/referenssit/sudenkorento/sk-0072-1600.jpg", "caption": "Koti B: tumma keitti\u00f6 ja tilaa kokoontua"}, {"alt": "Keitti\u00f6n mustat hanat, beige kaapistot ja tumma tasoryhm\u00e4", "url": "assets/img/referenssit/sudenkorento/sk-0069-1600.jpg", "caption": "Koti B: mustat hanat ja tummat kaapistot"}, {"alt": "Rauhallinen makuuhuone", "url": "assets/img/referenssit/sudenkorento/sk-0016-1600.jpg", "caption": "Makuuhuone"}, {"alt": "Makuuhuone ja kaapistot", "url": "assets/img/referenssit/sudenkorento/sk-0021-1600.jpg", "caption": "Reilusti s\u00e4ilytystilaa"}, {"alt": "Vihre\u00e4s\u00e4vyinen huone ja piano", "url": "assets/img/referenssit/sudenkorento/sk-0044-1600.jpg", "caption": "Persoonallinen huone vihre\u00e4ll\u00e4 sein\u00e4ll\u00e4"}, {"alt": "Huone, jossa on punaruskea tehostesein\u00e4", "url": "assets/img/referenssit/sudenkorento/sk-0083-1600.jpg", "caption": "Tehostesein\u00e4 tuo huoneeseen luonnetta"}, {"alt": "Kodinhoitohuone ja pyykinpesukone", "url": "assets/img/referenssit/sudenkorento/sk-0051-1600.jpg", "caption": "Kodinhoitohuone"}, {"alt": "Suihkutila vaalein laatoin", "url": "assets/img/referenssit/sudenkorento/sk-0090-1600.jpg", "caption": "Kylpyhuone"}, {"alt": "Wc ja allastila", "url": "assets/img/referenssit/sudenkorento/sk-0093-1600.jpg", "caption": "Wc ja allastila"}, {"alt": "Musta puutalo illan h\u00e4m\u00e4r\u00e4ss\u00e4, sis\u00e4\u00e4nk\u00e4ynnin valot palavat", "url": "assets/img/referenssit/sudenkorento/sk-0098-1600.jpg", "caption": "Illan tunnelma"}]$j$::jsonb, $j$[{"icon": "sun", "text": "Suuret ikkunat tuovat runsaasti luonnonvaloa jokaiseen huoneeseen ja avaavat n\u00e4kym\u00e4t vehre\u00e4\u00e4n ymp\u00e4rist\u00f6\u00f6n.", "title": "Valoa joka hetkess\u00e4"}, {"icon": "layout", "text": "Avara oleskelu-, keitti\u00f6- ja ruokailutila kokoaa perheen yhteen. Ei hukkaneli\u00f6it\u00e4, vain k\u00e4ytett\u00e4v\u00e4\u00e4 tilaa.", "title": "Yli 30 m\u00b2 yhteist\u00e4 tilaa"}, {"icon": "home", "text": "Vaatehuone, kodinhoitohuone ja varasto pit\u00e4v\u00e4t tavarat poissa silmist\u00e4 ja kodin rauhallisena.", "title": "S\u00e4ilytystilaa arkeen"}, {"icon": "euro", "text": "A-energialuokan koti, Puustellin kalusteet, induktioliesi ja erillisuuni, astianpesukone sek\u00e4 s\u00e4hk\u00f6kiuas saunassa.", "title": "Laatu ja pienet kulut"}, {"icon": "access", "text": "Esteet\u00f6n ja helppo liikkua. Kaksi wc:t\u00e4 helpottaa aamuja, ja koti toimii nuorelle perheelle yht\u00e4 hyvin kuin pienemp\u00e4\u00e4n kotiin muuttavalle.", "title": "Sopii kaikenik\u00e4isille"}, {"icon": "pin", "text": "Puistokaistaa ja mets\u00e4\u00e4 vasten rajautuva tontti, luontopolut ovelta, ja Limingan keskustan palvelut aivan l\u00e4hell\u00e4.", "title": "Rauha ja palvelut l\u00e4hell\u00e4"}]$j$::jsonb, E'Maaseudun rauha, keskustan palvelut', E'Limingan Kotiranta on omakotiasumisen unelmakohde keskell\u00e4 kaunista maaseutua, mutta silti aivan Limingan keskustan palveluiden \u00e4\u00e4rell\u00e4. Tontit rajautuvat puistokaistaan ja mets\u00e4\u00e4n, ja luontopoluille p\u00e4\u00e4see suoraan ovelta. Talvella l\u00e4htee hiiht\u00e4m\u00e4\u00e4n.\n\nTontille laaditaan hallinnanjakosopimus, jossa kukin hallinta-alue vastaa omista kustannuksistaan ja yhteiset kustannukset jaetaan tasan.', E'assets/img/referenssit/sudenkorento/sk-0107-1600.jpg', $j$[{"label": "Kohde", "value": "Sudenkorento 6 A ja B, Kotiranta, Liminka"}, {"label": "Talotyyppi", "value": "Kaksi erillistaloa (erillistalo kiinteist\u00f6)"}, {"label": "Asuinpinta-ala", "value": "82,5 m\u00b2 + 2,5 m\u00b2 muita tiloja"}, {"label": "Huoneistoselitelm\u00e4", "value": "4h + k + kph + s + vh + khh + var"}, {"label": "Energialuokka", "value": "A (2018)"}, {"label": "Rakennusvuosi", "value": "2026, uudisrakennus"}, {"label": "Keitti\u00f6", "value": "Puustellin kalusteet, j\u00e4\u00e4kaappi, pakastin, astianpesukone, induktioliesi ja erillisuuni"}, {"label": "Sauna", "value": "Paneelisein\u00e4t, laattalattia, s\u00e4hk\u00f6kiuas"}, {"label": "Tontti", "value": "1 380 m\u00b2, vuokratontti (Limingan kunta), kustannukset jaetaan kahden asunnon kesken"}, {"label": "Valinnat", "value": "Pihapys\u00e4k\u00f6inti tai autokatos, aurinkoterassi tai suojaisa katos"}]$j$::jsonb, E'kotiranta', true, 1)
ON CONFLICT (slug) DO NOTHING;
